void C3DBoundingBox::BuildFromPoints(const C3DVector* points, float num_points)
{
    if (num_points == 0.0f) {
        MinCoord.X = 0.0f;
        MinCoord.Y = 0.0f;
        MinCoord.Z = 0.0f;
        MaxCoord.X = 0.0f;
        MaxCoord.Y = 0.0f;
        MaxCoord.Z = 0.0f;
        return;
